// N+1 (반복마다 쿼리)
users = SELECT * FROM users;          // 1번
for u in users:
  u.orders = SELECT * FROM orders WHERE user_id = u.id;  // N번!

// 해결 1: 조인 (한 번)
SELECT u.*, o.* FROM users u JOIN orders o ON o.user_id = u.id;
// 해결 2: 일괄 조회 (두 번)
users = SELECT * FROM users;
